public String storyOfATree(int n, int[][] edges, int[][] guesses, int k) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    Set<Long> guessed = new HashSet<>();
    for (int[] g : guesses) {
        guessed.add((long) g[0] * (n + 1) + g[1]);   // directed: g0 is parent of g1
    }
    int wins = 0;
    for (int root = 1; root <= n; root++) {
        int correct = 0;
        boolean[] visited = new boolean[n + 1];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(root);
        visited[root] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    if (guessed.contains((long) u * (n + 1) + v)) correct++;
                    stack.push(v);
                }
            }
        }
        if (correct >= k) wins++;
    }
    int g = gcd(wins, n);
    return (wins / g) + "/" + (n / g);
}

private int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

