from math import gcd

def story_of_a_tree(self, n: int, edges: list[list[int]], guesses: list[list[int]], k: int) -> str:
    adj: list[list[int]] = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    guessed = {(a, b) for a, b in guesses}   # directed: a is parent of b
    wins = 0
    for root in range(1, n + 1):
        correct = 0
        visited = [False] * (n + 1)
        stack = [root]
        visited[root] = True
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    if (u, v) in guessed:
                        correct += 1
                    stack.append(v)
        if correct >= k:
            wins += 1
    g = gcd(wins, n)
    return f"{wins // g}/{n // g}"

