public String storyOfATree(int n, int[][] edges, int[][] guesses, int k) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    Set<Long> guessed = new HashSet<>();
    for (int[] g : guesses) {
        guessed.add((long) g[0] * (n + 1) + g[1]);   // directed pair
    }
    int[] parent = new int[n + 1];
    boolean[] visited = new boolean[n + 1];
    int[] order = new int[n];
    int oi = 0, base = 0;
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(1);
    visited[1] = true;
    while (!stack.isEmpty()) {
        int u = stack.pop();
        order[oi++] = u;
        for (int v : adj.get(u)) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                if (guessed.contains((long) u * (n + 1) + v)) base++;
                stack.push(v);
            }
        }
    }
    int[] correct = new int[n + 1];
    correct[1] = base;
    for (int i = 0; i < n; i++) {
        int u = order[i];
        for (int v : adj.get(u)) {
            if (parent[v] == u) {                 // v is a child of u
                int c = correct[u];
                if (guessed.contains((long) u * (n + 1) + v)) c--;   // u no longer parent of v
                if (guessed.contains((long) v * (n + 1) + u)) c++;   // v becomes parent of u
                correct[v] = c;
            }
        }
    }
    int wins = 0;
    for (int i = 1; i <= n; i++) if (correct[i] >= k) wins++;
    int g = gcd(wins, n);
    return (wins / g) + "/" + (n / g);
}

private int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

